// Parse Groq AI response
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';
const propertyData = $('Prepare Property Data').item.json.property_data;
const comparables = $('Prepare Property Data').item.json.comparables;

// Extract JSON from response
let parsed;
try {
  // Try to find JSON in markdown code blocks or raw
  const jsonMatch = content.match(/```json\s*([\s\S]*?)```/) || content.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : content;
  parsed = JSON.parse(jsonStr);
} catch (e) {
  // Fallback if JSON parsing fails
  console.log('JSON parse error:', e.message);
  parsed = {
    recommended_price_range: {
      minimum: propertyData.estimated_value ? propertyData.estimated_value * 0.9 : 0,
      target: propertyData.estimated_value || 0,
      maximum: propertyData.estimated_value ? propertyData.estimated_value * 1.1 : 0
    },
    price_per_sqm: {
      subject_estimate: 0,
      comparable_average: 0,
      market_average: 0
    },
    pricing_strategy: 'competitive',
    days_on_market_estimate: 45,
    market_positioning: 'average',
    key_value_factors: ['Location', 'Size'],
    value_concerns: ['Parse error - manual review needed'],
    comparables_analysis: {
      most_similar: 'unknown',
      adjustments_needed: ['Unable to analyze due to parse error']
    },
    recommendation_summary: 'AI analysis returned invalid format. Manual price review recommended.',
    confidence: 0.3
  };
}

// Ensure all required fields exist with defaults
const result = {
  property_id: propertyData.id || 'temp-' + Date.now(),
  property_address: propertyData.address || 'Unknown',
  suburb: propertyData.suburb || 'Unknown',
  recommended_min: parsed.recommended_price_range?.minimum || parsed.recommended_price_range?.min || 0,
  recommended_target: parsed.recommended_price_range?.target || parsed.recommended_price_range?.target_price || 0,
  recommended_max: parsed.recommended_price_range?.maximum || parsed.recommended_price_range?.max || 0,
  price_per_sqm_estimate: parsed.price_per_sqm?.subject_estimate || 0,
  pricing_strategy: parsed.pricing_strategy || 'competitive',
  days_on_market_estimate: parsed.days_on_market_estimate || 45,
  market_positioning: parsed.market_positioning || 'average',
  key_value_factors: parsed.key_value_factors || [],
  value_concerns: parsed.value_concerns || [],
  comparables_used: comparables.slice(0, 5).map(c => ({
    address: c.address,
    sale_price: c.sale_price,
    sale_date: c.sale_date,
    floor_size: c.floor_size,
    bedrooms: c.bedrooms,
    bathrooms: c.bathrooms
  })),
  recommendation_summary: parsed.recommendation_summary || 'Price recommendation generated',
  confidence: parsed.confidence || 0.5,
  comparables_analysis: parsed.comparables_analysis || {
    most_similar: 'unknown',
    adjustments_needed: []
  },
  generated_at: new Date().toISOString(),
  raw_response: content.substring(0, 2000) // Store truncated response for debugging
};

return [{
  json: result
}];

